/* ------------------------------------------------------------------ helpers */
L.sector=id=>L.sectors.find(s=>s.id===id)||null;
L.pick=(x,lang)=>x&&typeof x==='object'&&('ar' in x)?(lang==='en'?x.en:x.ar):(x??'');
L.goal=(sectorId,goalId)=>(L.sector(sectorId)?.goals||[]).find(g=>g.id===goalId)||null;
L.indicator=(sectorId,id)=>(L.sector(sectorId)?.indicators||[]).find(i=>i.id===id)||null;
L.reference=(sectorId,id)=>{const s=L.sector(sectorId);if(!s)return null;return s.regulations.find(r=>r.id===id)||null;};
L.program=(sectorId,id)=>(L.sector(sectorId)?.programs||[]).find(p=>p.id===id)||null;
L.goalsFor=(sectorId,typeId)=>(L.sector(sectorId)?.goals||[]).filter(g=>!g.types||!typeId||g.types.includes(typeId));
L.referencesFor=(sectorId,typeId)=>(L.sector(sectorId)?.regulations||[]).filter(r=>!r.types||!typeId||r.types.includes(typeId));
L.counts=sectorId=>{const s=L.sector(sectorId);return s?{regulations:s.regulations.length,programs:s.programs.length,indicators:s.indicators.length,goals:s.goals.length}:{regulations:0,programs:0,indicators:0,goals:0};};
/* Match a free-text sector label (e.g. the institution.sector field) to a library sector. */
L.detect=label=>{const v=String(label||'').toLowerCase();if(!v.trim())return null;const rules=[['edu',/مدرس|تعليم عام|k-12|school|روض|rawd/],['highered',/جامع|كلية|تعليم عال|univers|college|higher|معهد|institute/],['health',/صح|مستشف|طب|عياد|health|hospital|clinic|medical/],['nonprofit',/غير ربح|جمعي|وقف|خير|non-?profit|charit|foundation/],['tech',/تقني|برمج|سيبران|تقنية معلومات|رقمي|software|\bit\b|technolog|cyber|fintech|digital|cloud|systems integrat/],['gov',/حكوم|وزار|هيئ|أمان|بلدي|government|ministry|authority|regulat|municipal/]];for(const [id,re] of rules)if(re.test(v))return L.sector(id);return null;};
/* Compact grounding text for the AI research step: every reference the library knows for a sector. */
L.grounding=(sectorId,typeId,lang)=>{const s=L.sector(sectorId);if(!s)return '';const P=x=>L.pick(x,lang);const lines=[];lines.push((lang==='en'?'Sector: ':'القطاع: ')+P(s.name)+' · '+P(s.regulator));for(const p of s.programs)lines.push(`- [program] ${P(p.name)} — ${P(p.issuer)} — ${p.url}`);for(const r of L.referencesFor(sectorId,typeId))lines.push(`- [${r.kind}] ${P(r.name)} — ${P(r.issuer)} — ${r.url}`);for(const i of s.indicators)lines.push(`- [indicator] ${P(i.name)} (${P(i.unit)}, ${i.direction}) — ${P(i.dataSource)}`);return lines.join('\n');};
root.SultanLibrary=L;
